class Solution {
    public void gameOfLife(int[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        int[][] next = new int[rows][cols];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int liveNeighbors = 0;
                for (int rowOffset = -1; rowOffset <= 1; rowOffset++) {
                    for (int colOffset = -1; colOffset <= 1; colOffset++) {
                        if (rowOffset == 0 && colOffset == 0) continue;
                        int neighborRow = row + rowOffset;
                        int neighborCol = col + colOffset;
                        if (neighborRow >= 0 && neighborRow < rows && neighborCol >= 0 && neighborCol < cols) {
                            liveNeighbors += board[neighborRow][neighborCol];
                        }
                    }
                }
                if (board[row][col] == 1 && (liveNeighbors == 2 || liveNeighbors == 3)) next[row][col] = 1;
                if (board[row][col] == 0 && liveNeighbors == 3) next[row][col] = 1;
            }
        }
        for (int row = 0; row < rows; row++) {
            System.arraycopy(next[row], 0, board[row], 0, cols);
        }
    }
}

