class Solution {
    public void gameOfLife(int[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        int[] rowOffset = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] colOffset = {-1, 0, 1, -1, 1, -1, 0, 1};
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int liveNeighbors = 0;
                for (int direction = 0; direction < 8; direction++) {
                    int neighborRow = row + rowOffset[direction];
                    int neighborCol = col + colOffset[direction];
                    if (neighborRow >= 0 && neighborRow < rows && neighborCol >= 0 && neighborCol < cols) {
                        liveNeighbors += board[neighborRow][neighborCol] & 1;
                    }
                }
                if (liveNeighbors == 3 || (board[row][col] == 1 && liveNeighbors == 2)) {
                    board[row][col] |= 2;
                }
            }
        }
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                board[row][col] >>= 1;
            }
        }
    }
}
